async function openPlayer(publicId?:string){if(!publicId)return;const token=++profileRequest.current;setProfileOpen(true);setProfileLoading(true);setProfileError('');setViewedPlayer(null);try{const response=await fetch('/api/arena',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',...(session.current?{'X-Arena-Session':session.current}:{})},body:JSON.stringify({action:'view',publicId}),signal:AbortSignal.timeout(10000)});const result=await response.json() as {error?:string,viewedProfile?:PublicProfile|null};if(!response.ok)throw Error(result.error||'Could not load profile.');if(token!==profileRequest.current)return;if(!result.viewedProfile)throw Error('This profile is no longer available.');setViewedPlayer(result.viewedProfile);}catch(e){if(token===profileRequest.current)setProfileError((e as Error).message)}finally{if(token===profileRequest.current)setProfileLoading(false)}}
function historyList(entries:HistoryEntry[]){return <div className="history-list">{entries.map(h=><article key={h.id} className="history-row"><span className={'history-outcome '+(h.won?'won':'lost')}>{h.won?'WIN':'LOSS'}</span><div><div className="history-opponents">{(h.opponents||[h.opponent]).map((p,i)=><button key={p.publicId||i} className="player-link" disabled={!p.publicId} onClick={()=>openPlayer(p.publicId)}>{p.name} {p.publicId&&<ArrowRight size={12} aria-hidden="true"/>}</button>)}</div><small>{h.mode.toUpperCase()} · {h.playerCount||2} players{h.placement?` · #${h.placement}`:''} · {new Date(h.at).toLocaleDateString()} · {h.words} words{h.longest?` · Best: ${h.longest}`:''}{h.bestStreak?` · Best streak: ${h.bestStreak}`:''}</small></div><b className={h.delta!==null&&h.delta>=0?'history-gain':''}>{h.delta===null?'Unrated':`${h.delta>=0?'+':''}${h.delta} Elo`}</b></article>)}</div>}
function alphabetProgress(player:number){if(!m)return null;const letters=collectedLetters(m.words,player),earned=m.alphabetBonusUsed?.[player];return <div className="alphabet-player" key={player}>{player!==m.you&&<div className="alphabet-heading"><b>{m.players[player].name}</b><span>{letters.length}/26</span></div>}<div className="alphabet-grid" aria-label={`${player===m.you?'Your':m.players[player].name+'’s'} collected letters`}>{Array.from(alphabet).map(letter=><span key={letter} className={letters.includes(letter)?'collected':''} title={`${letter.toUpperCase()} ${letters.includes(letter)?'collected':'needed'}`}>{letter.toUpperCase()}</span>)}</div>{earned&&<div className="alphabet-earned" role="status"><Heart size={14} aria-hidden="true"/> +1 life earned · Bonus used</div>}</div>}
